-- ------------------------------------------------------------
-- Table: vcd_admin_users
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `vcd_admin_users` (
  `id` VARCHAR(64) NOT NULL,
  `username` VARCHAR(64) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `name` VARCHAR(128) NOT NULL,
  `role` ENUM('admin', 'editor', 'author') NOT NULL DEFAULT 'admin',
  `phone` VARCHAR(32) DEFAULT '',
  `status` ENUM('active', 'suspended') NOT NULL DEFAULT 'active',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `vcd_admin_users` (`id`, `username`, `password_hash`, `name`, `role`, `phone`, `status`) VALUES ('usr_admin', 'admin', '$2y$10$dxLpPbsGZxYZqACPQY4JJuZZU7XItfwTNKp85ZWAVZP5uZWMARFHO', 'Super Admin', 'admin', '+971 50 123 4567', 'active') ON DUPLICATE KEY UPDATE `password_hash`=VALUES(`password_hash`);
